// ExtractorFaultRecoveryStep is a test-only ordering probe. Production leaves it nil.
var ExtractorFaultRecoveryStep func(string)

func (bc *BlockChain) ExtractorRecover(fn func(*ExtractorRecovery) error) error {
	if ExtractorFaultRecoveryStep != nil {
		ExtractorFaultRecoveryStep("before-chain-lock")
	}
	if !bc.chainmu.TryLock() {
		return errChainStopped
	}
	defer bc.chainmu.Unlock()
	if ExtractorFaultRecoveryStep != nil {
		ExtractorFaultRecoveryStep("chain-locked")
	}
	return fn(&ExtractorRecovery{bc: bc})
}

